STORY_FIXES = [
    ("and He does. Elisha tells them", "and he does. Elisha tells them"),
    ("whoever hears of it will have both ears tingle", "whoever hears of it will have both ears tingle"),
    ("God speaks through his prophets: because of Manasseh's sins, He will bring", "God speaks through his prophets: because of Manasseh's sins, he will bring"),
    ("all the houses of Jerusalem.” his army breaks", "all the houses of Jerusalem.” His army breaks"),
    ("They may be taunting him to go up to heaven like Elijah.", "They are mocking him to go up to heaven as Elijah did."),
]


def apply_story_fixes():
    path = ROOT / "book_content" / "03_later_history.md"
    text = path.read_text(encoding="utf-8")
    start = text.index("# 2 Kings")
    try:
        end = text.index("\n# ", start + 5) + 1
    except ValueError:
        end = len(text)
    section = text[start:end]
    for old, new in STORY_FIXES:
        if old == new:
            continue
        if section.count(old) == 0:
            if section.count(new) == 0:
                print(f"story fix skipped (not found): {old!r}")
            continue
        section = section.replace(old, new)
    path.write_text(text[:start] + section + text[end:], encoding="utf-8")
    print(f"Updated {path.relative_to(ROOT)}")


if __name__ == "__main__":
    apply_chapter_insights()
    apply_book_overview()
    apply_story_fixes()
